  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content">
    <section class="panel" aria-labelledby="page-title">
      <p class="eyebrow">Preferences</p>
      <h1 id="page-title">Choose your notification channel</h1>
      <p class="intro">Tell us how you prefer to receive updates so we can deliver important alerts the way that works best for you.</p>

      <form id="notification-form" novalidate>
        <p class="required-note"><span class="required-mark" aria-hidden="true">*</span> Required field</p>

        <div class="form-field">
          <fieldset id="notification-group" aria-describedby="notification-help notification-error">
            <legend>How do you prefer to receive notifications? <span class="required-mark" aria-hidden="true">*</span></legend>
            <p class="field-help" id="notification-help">Choose one option before submitting your preference.</p>
            <p class="field-error" id="notification-error" hidden>Error: Select how you prefer to receive notifications.</p>

            <div class="radio-options">
              <label class="radio-card" for="notification-email">
                <input id="notification-email" type="radio" name="notificationPreference" value="Email" required>
                <span class="radio-copy">
                  <span class="radio-title">Email</span>
                  <span class="radio-description">Best for detailed updates and weekly summaries.</span>
                </span>
              </label>

              <label class="radio-card" for="notification-sms">
                <input id="notification-sms" type="radio" name="notificationPreference" value="SMS" required>
                <span class="radio-copy">
                  <span class="radio-title">SMS</span>
                  <span class="radio-description">Quick text alerts for time-sensitive activity.</span>
                </span>
              </label>

              <label class="radio-card" for="notification-push">
                <input id="notification-push" type="radio" name="notificationPreference" value="Push Notifications" required>
                <span class="radio-copy">
                  <span class="radio-title">Push Notifications</span>
                  <span class="radio-description">Real-time updates delivered straight to your device.</span>
                </span>
              </label>
            </div>
          </fieldset>
        </div>

        <button type="submit">Save preference</button>
        <p class="status" id="form-status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById("notification-form");
    const notificationGroup = document.getElementById("notification-group");
    const notificationError = document.getElementById("notification-error");
    const status = document.getElementById("form-status");
    const radios = Array.from(form.elements.namedItem("notificationPreference"));

    function setGroupError(hasError) {
      notificationError.hidden = !hasError;
      radios.forEach((radio) => {
        radio.setAttribute("aria-invalid", hasError ? "true" : "false");
      });
    }

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const selectedRadio = radios.find((radio) => radio.checked);

      if (!selectedRadio) {
        setGroupError(true);
        status.textContent = "";
        radios[0].focus();
        return;
      }

      setGroupError(false);
      status.textContent = "Preference saved: " + selectedRadio.value + ".";
    });

    radios.forEach((radio) => {
      radio.addEventListener("change", () => {
        if (radio.checked) {
          setGroupError(false);
          status.textContent = "";
        }
      });
    });
  </script>
